insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-M08$w$,$w$الفحص الدوري للوحات الكهربائية (البصري والحراري)$w$,$w$فنيو الكهرباء ومشرف الصيانة$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "يكشف الارتخاء والسخونة والتلف في اللوحات والقواطع قبل أن تتحول إلى انقطاع أو حريق. يشمل اللوحة الرئيسية (MDB) واللوحات الفرعية ولوحات الأحمال الحرجة (UPS). المرجع IEC 61439 وتوصيات الصانع."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- تصريح عمل للأعمال الكهربائية (M-01)، ولا يُفتح غطاء لوحة حية إلا لفني مؤهل\n- قفازات عازلة ونظارة وحذاء أمان، ولا خواتم ولا ساعات معدنية\n- مسافة آمنة أثناء التصوير الحراري ولوحة تحذير على اللوحة المفتوحة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- كاميرا حرارية\n- أمبير كلّابي وجهاز قياس جهد\n- مفاتيح عزم (Torque) ومفكات معزولة\n- مكنسة كهربائية للغبار وفرشاة غير موصلة\n- سجل اللوحات وجداول الدوائر"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | تحقق من وجود جدول الدوائر داخل اللوحة ومطابقته | الجدول موجود ومحدّث |\n| 2 | فحص بصري خارجي: الأبواب، الأقفال، اللوحات التحذيرية، عدم وجود تخزين أمام اللوحة (مسافة 1 م) | الممر خالٍ |\n| 3 | التصوير الحراري للوحة وهي تحت الحمل قبل أي فصل | الصور محفوظة بأرقام الدوائر |\n| 4 | قراءة التيار لكل طور ومقارنة الأطوار | عدم اتزان أقل من 10% |\n| 5 | بعد العزل (للصيانة السنوية): شد التوصيلات بالعزم المحدد من الصانع | التوصيلات مشدودة |\n| 6 | تنظيف الغبار وفحص علامات الحرارة والتغير اللوني والقواطع المتشققة | لا آثار حرارة |\n| 7 | اختبار زر الاختبار لقواطع التسرب الأرضي (RCD) | يفصل عند الاختبار |\n| 8 | إعادة التشغيل وتسجيل القراءات ورفع الصور في أمر العمل | الأمر مكتمل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الفحص البصري وقراءة الأحمال | شهرياً |\n| التصوير الحراري | كل 6 أشهر للوحات الحرجة، وسنوياً لغيرها |\n| شد التوصيلات والتنظيف | سنوياً |\n| اختبار قواطع التسرب | كل 3 أشهر |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا فرق حرارة أكثر من 15°م عن نقطة مماثلة (يُصلح فوراً) — وفرق 4–15°م يُجدول إصلاحه\n- الأطوار متوازنة والقواطع غير محمّلة فوق 80% من قيمتها\n- جدول الدوائر صحيح ومقروء"}, {"key": "donts", "title": "ممنوعات", "body": "- فتح لوحة حية بلا تصريح أو بلا معدات وقاية\n- تخزين مواد أمام اللوحات أو داخل غرفها\n- تكبير قيمة قاطع بدل معالجة سبب فصله"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "M-01 · M-03 · G-06 · R-45"}]$w$::jsonb,'wi',100,$w$bolt$w$,$w$الأنظمة الكهربائية$w$,$w$MNT$w$,$w$["تحقق من وجود جدول الدوائر داخل اللوحة ومطابقته", "فحص بصري خارجي: الأبواب، الأقفال، اللوحات التحذيرية، عدم وجود تخزين أمام اللوحة (مسافة 1 م)", "التصوير الحراري للوحة وهي تحت الحمل قبل أي فصل", "قراءة التيار لكل طور ومقارنة الأطوار", "بعد العزل (للصيانة السنوية): شد التوصيلات بالعزم المحدد من الصانع", "تنظيف الغبار وفحص علامات الحرارة والتغير اللوني والقواطع المتشققة", "اختبار زر الاختبار لقواطع التسرب الأرضي (RCD)", "إعادة التشغيل وتسجيل القراءات ورفع الصور في أمر العمل"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-M09$w$,$w$الصيانة الدورية لمضخات المياه ومجموعات الضغط$w$,$w$فنيو السباكة والميكانيكا$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "يضمن استمرار ضغط المياه في المنشأة وسلامة المضخات العاملة والاحتياطية وخزان الضغط. يشمل مضخات التغذية والتدوير ومجموعات الضغط (Booster)."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- عزل الكهرباء عن المضخة قبل فتحها (قفل ووسم)\n- قفازات وحذاء أمان، والحذر من الأرضية المبتلة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- مقياس ضغط\n- أمبير كلّابي\n- مفاتيح ومفكات\n- شحم مناسب لكراسي التحميل\n- منفاخ هواء لشحن خزان الضغط"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | قراءة ضغط التشغيل وضغط الإيقاف ومقارنتهما بالضبط المعتمد | ضمن الضبط |\n| 2 | التحقق من تبادل التشغيل بين المضخة العاملة والاحتياطية | التبادل يعمل |\n| 3 | قياس تيار المحرك ومقارنته بلوحة البيانات | لا يتجاوز التيار المقنن |\n| 4 | فحص الاهتزاز والصوت والتسريب من مانع التسرب الميكانيكي | لا تسريب ولا صوت غير طبيعي |\n| 5 | فحص ضغط الهواء المسبق في خزان الضغط والمضخة متوقفة والخزان مفرّغ | ضمن قيمة الصانع |\n| 6 | تنظيف المصافي (Strainers) وفحص صمامات عدم الرجوع | المصافي نظيفة |\n| 7 | فحص لوحة التحكم والحساسات وحماية التشغيل على الجاف | الحماية تعمل |\n| 8 | تسجيل القراءات وإغلاق أمر العمل | الأمر مكتمل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| القراءات والفحص البصري | أسبوعياً |\n| تبادل التشغيل وفحص خزان الضغط | شهرياً |\n| تنظيف المصافي والتشحيم | كل 3 أشهر |\n| الصيانة الشاملة | سنوياً |"}, {"key": "accept", "title": "معايير القبول", "body": "- الضغط مستقر ضمن الضبط في أبعد نقطة\n- المضختان صالحتان للتشغيل\n- لا تسريب"}, {"key": "donts", "title": "ممنوعات", "body": "- ترك المضخة الاحتياطية مفصولة\n- تشغيل المضخة بلا ماء\n- تعديل ضبط الضغط بلا تسجيل"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "G-06 · M-01 · R-45"}]$w$::jsonb,'wi',101,$w$wrench$w$,$w$الأنظمة الصحية$w$,$w$MNT$w$,$w$["قراءة ضغط التشغيل وضغط الإيقاف ومقارنتهما بالضبط المعتمد", "التحقق من تبادل التشغيل بين المضخة العاملة والاحتياطية", "قياس تيار المحرك ومقارنته بلوحة البيانات", "فحص الاهتزاز والصوت والتسريب من مانع التسرب الميكانيكي", "فحص ضغط الهواء المسبق في خزان الضغط والمضخة متوقفة والخزان مفرّغ", "تنظيف المصافي (Strainers) وفحص صمامات عدم الرجوع", "فحص لوحة التحكم والحساسات وحماية التشغيل على الجاف", "تسجيل القراءات وإغلاق أمر العمل"]$w$::jsonb,$w${"ppe": ["gloves", "boots"], "steps": [{"i": "gauge", "t": {"ar": "اقرأ ضغط التشغيل والإيقاف", "en": "Read start and stop pressure", "ur": "اسٹارٹ اور اسٹاپ پریشر پڑھیں", "bn": "চালু ও বন্ধের চাপ পড়ুন", "hi": "स्टार्ट और स्टॉप प्रेशर पढ़ें", "tl": "Basahin ang start at stop pressure"}}, {"i": "swap", "t": {"ar": "تأكد من تبادل المضختين", "en": "Check duty/standby changeover", "ur": "دونوں پمپوں کی باری چیک کریں", "bn": "দুই পাম্পের পালা পরিবর্তন দেখুন", "hi": "दोनों पंपों की अदला-बदली जांचें", "tl": "Suriin ang palitan ng dalawang pump"}}, {"i": "drop", "t": {"ar": "افحص التسريب والاهتزاز", "en": "Check leaks and vibration", "ur": "لیکیج اور ارتعاش چیک کریں", "bn": "লিক ও কম্পন দেখুন", "hi": "लीक और कंपन जांचें", "tl": "Suriin ang tagas at pagyanig"}}, {"i": "tank", "t": {"ar": "افحص هواء خزان الضغط", "en": "Check pressure vessel air charge", "ur": "پریشر ٹینک کی ہوا چیک کریں", "bn": "প্রেসার ট্যাংকের বাতাস দেখুন", "hi": "प्रेशर टैंक की हवा जांचें", "tl": "Suriin ang hangin ng pressure tank"}}, {"i": "filter", "t": {"ar": "نظّف المصافي", "en": "Clean the strainers", "ur": "اسٹرینر صاف کریں", "bn": "স্ট্রেইনার পরিষ্কার করুন", "hi": "स्ट्रेनर साफ करें", "tl": "Linisin ang mga strainer"}}, {"i": "clipboard", "t": {"ar": "سجّل القراءات", "en": "Record the readings", "ur": "ریڈنگ لکھیں", "bn": "রিডিং লিখুন", "hi": "रीडिंग लिखें", "tl": "Itala ang mga reading"}}], "donts": [{"i": "nowater_elec", "t": {"ar": "لا تفتح المضخة والكهرباء موصولة", "en": "Never open the pump while energized", "ur": "بجلی لگی ہو تو پمپ نہ کھولیں", "bn": "বিদ্যুৎ চালু থাকলে পাম্প খুলবেন না", "hi": "बिजली चालू हो तो पंप न खोलें", "tl": "Huwag buksan ang pump habang may kuryente"}}]}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-M10$w$,$w$الصيانة الدورية للأبواب الأوتوماتيكية$w$,$w$فنيو الصيانة ووكيل الأبواب$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "يحافظ على عمل الأبواب الأوتوماتيكية بأمان في المداخل ومسارات الإخلاء: الحساسات، وفتح الباب عند الإنذار وانقطاع الكهرباء (Fail-safe)، والبطارية الاحتياطية. المرجع EN 16005 وتعليمات الصانع."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- تحويل الباب إلى وضع «مفتوح» أو «يدوي» وحجز منطقة العمل بلوحة تحذير\n- العمل خارج أوقات الذروة في المداخل الرئيسية"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- مفاتيح ومفكات\n- منظف للمسارات ومزلّق جاف حسب الصانع\n- أداة قياس قوة الإغلاق إن توفرت"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | تنظيف مسار الأرضية والمسار العلوي والعجلات | المسار نظيف |\n| 2 | اختبار الحساسات من الجهتين بالمرور البطيء | يفتح قبل الوصول |\n| 3 | اختبار حساس الأمان: وضع عائق في منتصف الفتحة أثناء الإغلاق | يرتد ولا يغلق على العائق |\n| 4 | فصل الكهرباء والتأكد أن الباب يفتح ويبقى مفتوحاً بالبطارية | يعمل بالبطارية |\n| 5 | اختبار الربط مع إنذار الحريق (بالتنسيق مع السلامة) | يفتح فتحاً كاملاً عند الإنذار |\n| 6 | فحص مفتاح الأوضاع وإقفال الليل | كل الأوضاع تعمل |\n| 7 | ضبط السرعة وقوة الإغلاق وتسجيل الأمر | ضمن قيم الصانع |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| اختبار الحساسات والأمان | أسبوعياً من المنشأة |\n| الصيانة الوقائية الكاملة | كل 3 أشهر |\n| اختبار البطارية والربط بالإنذار | كل 6 أشهر |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا يغلق الباب على شخص أو كرسي\n- يفتح عند الإنذار وعند انقطاع الكهرباء\n- لا أصوات احتكاك"}, {"key": "donts", "title": "ممنوعات", "body": "- تعطيل حساس الأمان لتسريع الإغلاق\n- ترك الباب على «مغلق» في ساعات العمل\n- تشحيم المسار بمواد تجمع الغبار"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "G-06 · G-05 · R-45"}]$w$::jsonb,'wi',102,$w$building$w$,$w$الأبواب والمداخل$w$,$w$MNT$w$,$w$["تنظيف مسار الأرضية والمسار العلوي والعجلات", "اختبار الحساسات من الجهتين بالمرور البطيء", "اختبار حساس الأمان: وضع عائق في منتصف الفتحة أثناء الإغلاق", "فصل الكهرباء والتأكد أن الباب يفتح ويبقى مفتوحاً بالبطارية", "اختبار الربط مع إنذار الحريق (بالتنسيق مع السلامة)", "فحص مفتاح الأوضاع وإقفال الليل", "ضبط السرعة وقوة الإغلاق وتسجيل الأمر"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-M11$w$,$w$صيانة الأطقم الصحية والخلاطات والخزانات المخفية$w$,$w$فنيو السباكة$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "إصلاح التسريبات وأعطال الخلاطات وصناديق الطرد في دورات المياه بأقل إزعاج للمنشأة ودون تكسير التشطيبات. الخزانات المخفية تُصان من فتحة لوحة الدفع، وقطعها من وكيل الصانع."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- قفازات وحذاء أمان، ولوحة «أرضية مبتلة»\n- إغلاق محبس المنطقة قبل الفك\n- التطهير بعد العمل في دورات المياه"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- مفاتيح وأدوات سباكة\n- قطع غيار أصلية للخلاطات والخزانات (حسب الماركة المعتمدة)\n- سيليكون صحي مضاد للفطريات\n- معقم"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | تحديد العطل وإغلاق محبس المنطقة أو الجهاز | المياه مغلقة |\n| 2 | للخزان المخفي: فك لوحة الدفع والوصول من فتحتها دون تكسير | لا تكسير |\n| 3 | استبدال القطعة التالفة بقطعة أصلية مطابقة للموديل | القطعة مطابقة |\n| 4 | للخلاط: فحص الخرطوشة والفلتر وتنظيف الترسبات | التدفق طبيعي |\n| 5 | فتح المياه واختبار التسريب 10 دقائق | لا تسريب |\n| 6 | تجديد السيليكون التالف حول المغاسل والأرضيات | السيليكون سليم |\n| 7 | تنظيف المكان وتطهيره وإزالة لوحة التحذير | المكان نظيف |\n| 8 | تسجيل القطعة المستبدلة في أمر العمل | الأمر مكتمل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| جولة فحص التسريبات | أسبوعياً |\n| تنظيف فلاتر الخلاطات | كل 3 أشهر |\n| تجديد السيليكون | عند التلف وسنوياً للمراجعة |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا تسريب ولا رطوبة حول القطع\n- صندوق الطرد يتوقف بعد الامتلاء\n- السيليكون نظيف بلا فطريات"}, {"key": "donts", "title": "ممنوعات", "body": "- تكسير البلاط للوصول للخزان المخفي\n- تركيب قطع غير أصلية أو غير مطابقة\n- ترك الأرضية مبتلة بلا لوحة تحذير"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "G-05 · G-06"}]$w$::jsonb,'wi',103,$w$wrench$w$,$w$الأنظمة الصحية$w$,$w$MNT$w$,$w$["تحديد العطل وإغلاق محبس المنطقة أو الجهاز", "للخزان المخفي: فك لوحة الدفع والوصول من فتحتها دون تكسير", "استبدال القطعة التالفة بقطعة أصلية مطابقة للموديل", "للخلاط: فحص الخرطوشة والفلتر وتنظيف الترسبات", "فتح المياه واختبار التسريب 10 دقائق", "تجديد السيليكون التالف حول المغاسل والأرضيات", "تنظيف المكان وتطهيره وإزالة لوحة التحذير", "تسجيل القطعة المستبدلة في أمر العمل"]$w$::jsonb,$w${"ppe": ["gloves", "boots", "wetsign"], "steps": [{"i": "valve", "t": {"ar": "أغلق محبس المياه", "en": "Close the water valve", "ur": "پانی کا والو بند کریں", "bn": "পানির ভালভ বন্ধ করুন", "hi": "पानी का वाल्व बंद करें", "tl": "Isara ang balbula ng tubig"}}, {"i": "wrench", "t": {"ar": "افتح من فتحة لوحة الدفع فقط", "en": "Access only through the flush plate", "ur": "صرف فلش پلیٹ کے راستے کھولیں", "bn": "শুধু ফ্লাশ প্লেট দিয়ে খুলুন", "hi": "केवल फ्लश प्लेट से खोलें", "tl": "Sa flush plate lang dumaan"}}, {"i": "swap", "t": {"ar": "ركّب قطعة أصلية مطابقة", "en": "Fit a genuine matching part", "ur": "اصل اور مماثل پرزہ لگائیں", "bn": "আসল ও মিলে যাওয়া পার্টস লাগান", "hi": "असली और मेल खाता पार्ट लगाएं", "tl": "Maglagay ng orihinal na piyesa"}}, {"i": "drop", "t": {"ar": "اختبر التسريب 10 دقائق", "en": "Check for leaks for 10 minutes", "ur": "10 منٹ لیکیج چیک کریں", "bn": "১০ মিনিট লিক দেখুন", "hi": "10 मिनट लीक जांचें", "tl": "Suriin ang tagas ng 10 minuto"}}, {"i": "spray", "t": {"ar": "نظّف وطهّر المكان", "en": "Clean and disinfect the area", "ur": "جگہ صاف اور جراثیم سے پاک کریں", "bn": "জায়গা পরিষ্কার ও জীবাণুমুক্ত করুন", "hi": "जगह साफ और कीटाणुरहित करें", "tl": "Linisin at i-disinfect ang lugar"}}], "donts": [{"i": "noglass", "t": {"ar": "لا تكسر البلاط", "en": "Do not break tiles", "ur": "ٹائلیں نہ توڑیں", "bn": "টাইলস ভাঙবেন না", "hi": "टाइलें न तोड़ें", "tl": "Huwag basagin ang tiles"}}, {"i": "nowet", "t": {"ar": "لا تترك الأرضية مبتلة", "en": "Do not leave the floor wet", "ur": "فرش گیلا نہ چھوڑیں", "bn": "মেঝে ভেজা রাখবেন না", "hi": "फर्श गीला न छोड़ें", "tl": "Huwag iwanang basa ang sahig"}}]}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-S03$w$,$w$الاختبار الدوري لمضخات الحريق$w$,$w$فنيو أنظمة الحريق ومشرف السلامة$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "يثبت أن مضخات الحريق ستعمل آلياً عند انخفاض ضغط الشبكة. المرجع NFPA 25: مضخة الديزل تُشغَّل أسبوعياً 30 دقيقة، والكهربائية شهرياً 10 دقائق على الأقل، واختبار التدفق سنوياً."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- إبلاغ المنشأة وغرفة المراقبة قبل الاختبار حتى لا يُعامل كإنذار\n- حماية السمع قرب مضخة الديزل\n- لا تدخين ولا لهب قرب خزان الوقود"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- سجل مضخات الحريق\n- مقياس ضغط\n- مقياس سرعة الدوران إن توفر"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | فحص غرفة المضخات: الحرارة، الإضاءة، التهوية، عدم وجود تسريب | الغرفة سليمة |\n| 2 | التحقق أن كل المحابس الرئيسية مفتوحة ومراقبة | المحابس في وضعها |\n| 3 | فحص وقود الديزل والزيت وماء التبريد والبطاريتين وشاحنهما | المستويات سليمة |\n| 4 | بدء التشغيل الآلي بخفض الضغط من محبس الاختبار (لا من اللوحة يدوياً) | أقلعت آلياً |\n| 5 | تسجيل ضغط الإقلاع وضغط السحب والطرد | ضمن قيم المضخة |\n| 6 | تشغيل الديزل 30 دقيقة والكهربائية 10 دقائق ومراقبة الحرارة والتسريب وصمام التنفيس | لا ارتفاع حرارة |\n| 7 | إعادة اللوحات إلى الوضع الآلي | الوضع «آلي» |\n| 8 | تسجيل كل القراءات وإغلاق الأمر | الأمر مكتمل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| اختبار مضخة الديزل | أسبوعياً — 30 دقيقة |\n| اختبار المضخة الكهربائية | شهرياً — 10 دقائق |\n| اختبار التدفق الكامل | سنوياً بمقاول معتمد |\n| مضخة الجوكي | مع كل اختبار |"}, {"key": "accept", "title": "معايير القبول", "body": "- الإقلاع آلي عند ضغط الضبط\n- الضغوط مستقرة ولا حرارة زائدة\n- اللوحات على «آلي» بعد الاختبار"}, {"key": "donts", "title": "ممنوعات", "body": "- ترك لوحة المضخة على يدوي أو إيقاف\n- إغلاق محبس رئيسي دون إجراء التعطيل (H-01)\n- تجاهل إنذار في لوحة المضخة"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "H-01 · H-06 · M-03 · R-14"}]$w$::jsonb,'wi',104,$w$flame$w$,$w$السلامة من الحريق$w$,$w$SAF$w$,$w$["فحص غرفة المضخات: الحرارة، الإضاءة، التهوية، عدم وجود تسريب", "التحقق أن كل المحابس الرئيسية مفتوحة ومراقبة", "فحص وقود الديزل والزيت وماء التبريد والبطاريتين وشاحنهما", "بدء التشغيل الآلي بخفض الضغط من محبس الاختبار (لا من اللوحة يدوياً)", "تسجيل ضغط الإقلاع وضغط السحب والطرد", "تشغيل الديزل 30 دقيقة والكهربائية 10 دقائق ومراقبة الحرارة والتسريب وصمام التنفيس", "إعادة اللوحات إلى الوضع الآلي", "تسجيل كل القراءات وإغلاق الأمر"]$w$::jsonb,$w${"ppe": ["ear", "gloves"], "steps": [{"i": "phone", "t": {"ar": "أبلغ المنشأة قبل الاختبار", "en": "Notify the facility before the test", "ur": "ٹیسٹ سے پہلے سہولت کو بتائیں", "bn": "টেস্টের আগে ফ্যাসিলিটিকে জানান", "hi": "टेस्ट से पहले सुविधा को बताएं", "tl": "Abisuhan ang pasilidad bago ang test"}}, {"i": "valve", "t": {"ar": "تأكد أن المحابس مفتوحة", "en": "Check main valves are open", "ur": "مین والو کھلے ہیں چیک کریں", "bn": "মূল ভালভ খোলা আছে দেখুন", "hi": "मुख्य वाल्व खुले हैं जांचें", "tl": "Tiyaking bukas ang mga balbula"}}, {"i": "fuel", "t": {"ar": "افحص الوقود والزيت والبطاريات", "en": "Check fuel, oil and batteries", "ur": "ایندھن، تیل اور بیٹریاں چیک کریں", "bn": "জ্বালানি, তেল ও ব্যাটারি দেখুন", "hi": "ईंधन, तेल और बैटरी जांचें", "tl": "Suriin ang gasolina, langis at baterya"}}, {"i": "gauge", "t": {"ar": "خفّض الضغط ودع المضخة تقلع آلياً", "en": "Drop pressure — pump must auto‑start", "ur": "پریشر کم کریں — پمپ خود چلے", "bn": "চাপ কমান — পাম্প নিজে চালু হবে", "hi": "प्रेशर घटाएं — पंप खुद चालू हो", "tl": "Babaan ang presyon — dapat kusang umandar"}}, {"i": "clock", "t": {"ar": "الديزل 30 دقيقة، الكهربائية 10", "en": "Diesel 30 min, electric 10 min", "ur": "ڈیزل 30 منٹ، الیکٹرک 10 منٹ", "bn": "ডিজেল ৩০ মিনিট, ইলেকট্রিক ১০ মিনিট", "hi": "डीजल 30 मिनट, इलेक्ट्रिक 10 मिनट", "tl": "Diesel 30 min, de-kuryente 10 min"}}, {"i": "auto", "t": {"ar": "أعد اللوحة إلى «آلي»", "en": "Return the panel to AUTO", "ur": "پینل واپس \"آٹو\" پر کریں", "bn": "প্যানেল আবার \"অটো\" করুন", "hi": "पैनल वापस \"ऑटो\" पर करें", "tl": "Ibalik ang panel sa AUTO"}}], "donts": [{"i": "nomanual", "t": {"ar": "لا تترك اللوحة على يدوي", "en": "Never leave the panel on MANUAL", "ur": "پینل مینوئل پر نہ چھوڑیں", "bn": "প্যানেল ম্যানুয়ালে রাখবেন না", "hi": "पैनल मैनुअल पर न छोड़ें", "tl": "Huwag iwan ang panel sa MANUAL"}}, {"i": "nofire", "t": {"ar": "لا تدخين قرب الوقود", "en": "No smoking near fuel", "ur": "ایندھن کے قریب سگریٹ منع", "bn": "জ্বালানির কাছে ধূমপান নিষেধ", "hi": "ईंधन के पास धूम्रपान मना", "tl": "Bawal manigarilyo malapit sa gasolina"}}]}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-S04$w$,$w$الاختبار الدوري لنظام إنذار الحريق$w$,$w$فنيو أنظمة الحريق ومقاول الصيانة$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "يضمن أن كل كاشف ونقطة نداء وجهاز إنذار يعمل ويُظهر موقعه الصحيح في اللوحة وفي المراقبة المركزية، وأن الربط مع التكييف والأبواب والمصاعد والإذاعة يعمل. المرجع NFPA 72 واشتراطات الدفاع المدني."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- إبلاغ المنشأة وغرفة المراقبة قبل الاختبار وبعده\n- عزل الأجزاء المختبرة فقط ولأقصر وقت (H-01)\n- سلم آمن للكواشف المرتفعة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- أداة اختبار الكواشف (دخان صناعي / حرارة) بعمود\n- مفتاح نقاط النداء\n- قائمة عناوين الأجهزة\n- سجل الاختبار"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | مراجعة اللوحة: لا أعطال ولا أجزاء معزولة منسية | اللوحة سليمة |\n| 2 | إبلاغ المنشأة والمراقبة وتحديد المنطقة المختبرة | الإبلاغ تم |\n| 3 | اختبار كل كاشف بأداة الاختبار والتأكد من ظهور عنوانه الصحيح | العنوان مطابق |\n| 4 | اختبار نقاط النداء اليدوية بالمفتاح | تعمل وتعود |\n| 5 | التحقق من الأجراس والأضواء وسماعات الإخلاء في المنطقة | مسموعة ومرئية |\n| 6 | اختبار الربط: إيقاف التكييف، فتح الأبواب، استدعاء المصعد، رسالة الإخلاء | كل الربط يعمل |\n| 7 | فحص البطاريات الاحتياطية للوحة | ضمن قيمتها |\n| 8 | إعادة كل المناطق للخدمة وتسجيل نتائج كل جهاز | لا منطقة معزولة |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الفحص البصري للوحة | يومياً من المنشأة |\n| اختبار عينة من الأجهزة والربط | كل 3 أشهر |\n| اختبار كل الأجهزة 100% | سنوياً |\n| البطاريات | كل 6 أشهر |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل جهاز اختُبر وسُجّل بعنوانه\n- الإنذار يصل للمراقبة المركزية\n- لا منطقة معزولة بعد الاختبار"}, {"key": "donts", "title": "ممنوعات", "body": "- ترك منطقة معزولة بعد الاختبار\n- تغطية كاشف أو إزالته بلا إجراء تعطيل\n- إسكات إنذار حقيقي دون تحقق"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "H-01 · H-06 · M-03 · R-14"}]$w$::jsonb,'wi',105,$w$siren$w$,$w$السلامة من الحريق$w$,$w$SAF$w$,$w$["مراجعة اللوحة: لا أعطال ولا أجزاء معزولة منسية", "إبلاغ المنشأة والمراقبة وتحديد المنطقة المختبرة", "اختبار كل كاشف بأداة الاختبار والتأكد من ظهور عنوانه الصحيح", "اختبار نقاط النداء اليدوية بالمفتاح", "التحقق من الأجراس والأضواء وسماعات الإخلاء في المنطقة", "اختبار الربط: إيقاف التكييف، فتح الأبواب، استدعاء المصعد، رسالة الإخلاء", "فحص البطاريات الاحتياطية للوحة", "إعادة كل المناطق للخدمة وتسجيل نتائج كل جهاز"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-S05$w$,$w$الفحص الشهري لأبواب الحريق ومخارج الطوارئ$w$,$w$مشرف السلامة وفنيو الصيانة$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "باب الحريق يحمي مسار الإخلاء فقط إذا أغلق وأحكم ذاتياً. يفحص هذا العمل الأبواب المقاومة للحريق وأذرع الخروج ومسارات الإخلاء. المرجع NFPA 80 وNFPA 101 والدفاع المدني."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- لا تُجرَّب أذرع الخروج المربوطة بالإنذار دون تنسيق مع غرفة المراقبة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- قائمة أبواب الحريق بمواقعها\n- مفكات ومفتاح ألن لضبط المغلقات\n- ملصقات «لا تسند هذا الباب»"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | التأكد أن الباب غير مسنود بإسفين أو كرسي أو مربوط | الباب حر |\n| 2 | فتح الباب 90° وتركه: يجب أن يغلق ذاتياً ويُحكم القفل | يغلق ويُحكم |\n| 3 | فحص الملصق التعريفي لتصنيف الحريق على الباب والحلق | الملصق موجود |\n| 4 | فحص الشريط المانع للدخان والفراغ أسفل الباب | سليم |\n| 5 | اختبار ذراع الخروج: يفتح بضغطة واحدة دون مفتاح | يفتح بسهولة |\n| 6 | مسار الإخلاء خالٍ ولوحة المخرج مضاءة | المسار خالٍ |\n| 7 | تسجيل كل باب بنتيجته ورفع صورة لأي باب معيب وفتح أمر إصلاح | الأمر مكتمل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| جولة الأبواب ومسارات الإخلاء | شهرياً |\n| الفحص الموثق الكامل | سنوياً وفق NFPA 80 |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل باب يغلق ويُحكم ذاتياً\n- لا عوائق في مسارات الإخلاء\n- أذرع الخروج تعمل"}, {"key": "donts", "title": "ممنوعات", "body": "- إسناد باب الحريق مفتوحاً\n- فك المغلق أو تعطيله\n- تخزين أي شيء في مسار الإخلاء أو أمام المخرج"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "H-06 · H-02 · R-14"}]$w$::jsonb,'wi',106,$w$shield$w$,$w$السلامة من الحريق$w$,$w$SAF$w$,$w$["التأكد أن الباب غير مسنود بإسفين أو كرسي أو مربوط", "فتح الباب 90° وتركه: يجب أن يغلق ذاتياً ويُحكم القفل", "فحص الملصق التعريفي لتصنيف الحريق على الباب والحلق", "فحص الشريط المانع للدخان والفراغ أسفل الباب", "اختبار ذراع الخروج: يفتح بضغطة واحدة دون مفتاح", "مسار الإخلاء خالٍ ولوحة المخرج مضاءة", "تسجيل كل باب بنتيجته ورفع صورة لأي باب معيب وفتح أمر إصلاح"]$w$::jsonb,$w${"steps": [{"i": "door", "t": {"ar": "تأكد أن الباب غير مسنود", "en": "Make sure the door is not wedged open", "ur": "دیکھیں دروازہ اٹکایا نہ گیا ہو", "bn": "দরজা আটকে রাখা নেই দেখুন", "hi": "देखें दरवाजा अटका न हो", "tl": "Tiyaking hindi nakaharang ang pinto"}}, {"i": "auto", "t": {"ar": "افتحه واتركه: يجب أن يغلق وحده", "en": "Open and release: it must self‑close", "ur": "کھول کر چھوڑیں: خود بند ہو", "bn": "খুলে ছেড়ে দিন: নিজে বন্ধ হবে", "hi": "खोलकर छोड़ें: खुद बंद हो", "tl": "Buksan at bitawan: kusang sasara"}}, {"i": "label", "t": {"ar": "تحقق من ملصق الحريق", "en": "Check the fire rating label", "ur": "فائر لیبل چیک کریں", "bn": "ফায়ার লেবেল দেখুন", "hi": "फायर लेबल जांचें", "tl": "Suriin ang fire label"}}, {"i": "exit", "t": {"ar": "مسار الإخلاء خالٍ ومضاء", "en": "Escape route clear and lit", "ur": "راستہ خالی اور روشن ہو", "bn": "পথ খালি ও আলোকিত", "hi": "रास्ता खाली और रोशन हो", "tl": "Malinis at may ilaw ang daanan"}}, {"i": "camera", "t": {"ar": "صوّر أي عيب وبلّغ", "en": "Photograph and report any fault", "ur": "خرابی کی تصویر لیں اور بتائیں", "bn": "ত্রুটির ছবি তুলে জানান", "hi": "खराबी की फोटो लें और बताएं", "tl": "Kunan ng larawan at i-report"}}], "donts": [{"i": "noblock", "t": {"ar": "لا تضع شيئاً في المسار", "en": "Never block the route", "ur": "راستے میں کچھ نہ رکھیں", "bn": "পথে কিছু রাখবেন না", "hi": "रास्ते में कुछ न रखें", "tl": "Huwag harangan ang daanan"}}, {"i": "nocover", "t": {"ar": "لا تسند باب الحريق", "en": "Never prop a fire door open", "ur": "فائر ڈور کھلا نہ اٹکائیں", "bn": "ফায়ার ডোর খোলা রাখবেন না", "hi": "फायर डोर खुला न अटकाएं", "tl": "Huwag ibukas nang naka-tukod ang fire door"}}]}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-F01$w$,$w$تركيب شاشة عرض وفق معيار التجمع$w$,$w$فنيو الصيانة وتقنية المعلومات والمقاولون$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "كل شاشة تُركَّب في منشآت التجمع تتبع معيار الشاشات الرقمية AAHC-FM-STD-DIGITAL-SIGNAGE-001 (R-46): الموديل والمقاس والارتفاع حسب الموقع، ومقبسان ونقطة شبكة خلف الشاشة، وكابلات مخفية، وربط شاشات المناطق العامة بمنصة Navori."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- التأكد من نوع الجدار وتحمّله قبل الحفر، وعدم الحفر فوق مسارات التمديدات\n- سلم آمن وشخصان لرفع الشاشة\n- إغلاق المنطقة بلوحة أثناء العمل في الأماكن العامة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- حامل تجاري معتمد مناسب لوزن الشاشة\n- ميزان ماء وشريط قياس\n- كاشف تمديدات داخل الجدار\n- مثقاب وبراغي ومثبتات مناسبة لنوع الجدار\n- مجاري كابلات مخفية"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | تأكيد الموقع والمقاس من جدول المعيار (مثلاً: انتظار صغير 43–55 بوصة، ردهة رئيسية 65–75) | المقاس مطابق |\n| 2 | تحديد ارتفاع منتصف الشاشة من الأرضية المنتهية حسب الموقع (الانتظار 1.5–1.7 م، الردهة 1.7–2.0 م، الاجتماعات 1.2–1.4 م) | الارتفاع مطابق |\n| 3 | التأكد من وجود مقبسين خلف موقع الشاشة (أحدهما على الطوارئ/UPS حيث أمكن) ونقطة شبكة RJ45 | النقاط موجودة |\n| 4 | تثبيت الحامل بالميزان ومثبتات مناسبة للجدار | الحامل أفقي ومحكم |\n| 5 | تعليق الشاشة وتوصيل الكهرباء والشبكة والمشغّل خلفها | كل التوصيلات مخفية |\n| 6 | ربط الشاشة بمنصة Navori مع تقنية المعلومات (للمناطق العامة) | تظهر في المنصة |\n| 7 | تصوير الشاشة بعد التركيب وتسجيلها بموقعها وموديلها ومقاسها | مسجلة في سجل الأصول |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| التركيب | عند كل طلب أو مشروع |\n| فحص التثبيت والكابلات | سنوياً ضمن جولة المرافق |"}, {"key": "accept", "title": "معايير القبول", "body": "- شاشة تجارية معتمدة لا تلفزيون منزلي في المناطق العامة\n- لا كابلات ظاهرة ولا تمديدات مؤقتة\n- الارتفاع والمقاس حسب المعيار\n- مربوطة بـ Navori ومسجلة"}, {"key": "donts", "title": "ممنوعات", "body": "- تركيب تلفزيون منزلي في مكان عام\n- تمديدة كهرباء ظاهرة أو أسلاك متدلية\n- الحفر دون فحص الجدار"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "F-03 · G-12 · T-02 · R-46"}]$w$::jsonb,'wi',107,$w$monitor$w$,$w$التجهيزات والمرافق$w$,$w$FAC$w$,$w$["تأكيد الموقع والمقاس من جدول المعيار (مثلاً: انتظار صغير 43–55 بوصة، ردهة رئيسية 65–75)", "تحديد ارتفاع منتصف الشاشة من الأرضية المنتهية حسب الموقع (الانتظار 1.5–1.7 م، الردهة 1.7–2.0 م، الاجتماعات 1.2–1.4 م)", "التأكد من وجود مقبسين خلف موقع الشاشة (أحدهما على الطوارئ/UPS حيث أمكن) ونقطة شبكة RJ45", "تثبيت الحامل بالميزان ومثبتات مناسبة للجدار", "تعليق الشاشة وتوصيل الكهرباء والشبكة والمشغّل خلفها", "ربط الشاشة بمنصة Navori مع تقنية المعلومات (للمناطق العامة)", "تصوير الشاشة بعد التركيب وتسجيلها بموقعها وموديلها ومقاسها"]$w$::jsonb,$w${"ppe": ["ladder"], "steps": [{"i": "clipboard", "t": {"ar": "تأكد من المقاس والارتفاع حسب الموقع", "en": "Confirm size and height for the location", "ur": "جگہ کے مطابق سائز اور اونچائی چیک کریں", "bn": "জায়গা অনুযায়ী মাপ ও উচ্চতা দেখুন", "hi": "जगह के अनुसार साइज और ऊंचाई जांचें", "tl": "Kumpirmahin ang laki at taas"}}, {"i": "power", "t": {"ar": "مقبسان ونقطة شبكة خلف الشاشة", "en": "Two sockets and a network point behind", "ur": "پیچھے دو ساکٹ اور نیٹ ورک پوائنٹ", "bn": "পেছনে দুটি সকেট ও নেটওয়ার্ক পয়েন্ট", "hi": "पीछे दो सॉकेट और नेटवर्क पॉइंट", "tl": "Dalawang saksakan at network sa likod"}}, {"i": "check", "t": {"ar": "ثبّت الحامل بالميزان", "en": "Fix the bracket level", "ur": "بریکٹ سیدھا لگائیں", "bn": "ব্র্যাকেট সোজা করে লাগান", "hi": "ब्रैकेट सीधा लगाएं", "tl": "Ikabit nang pantay ang bracket"}}, {"i": "screen", "t": {"ar": "علّق الشاشة وأخفِ كل الكابلات", "en": "Hang the screen and hide all cables", "ur": "اسکرین لگائیں اور تار چھپائیں", "bn": "স্ক্রিন লাগিয়ে সব তার লুকান", "hi": "स्क्रीन लगाएं और तार छिपाएं", "tl": "Isabit ang screen at itago ang kable"}}, {"i": "camera", "t": {"ar": "صوّرها وسجّلها", "en": "Photograph and register it", "ur": "تصویر لیں اور رجسٹر کریں", "bn": "ছবি তুলে নিবন্ধন করুন", "hi": "फोटो लें और दर्ज करें", "tl": "Kunan ng larawan at irehistro"}}], "donts": [{"i": "nocover", "t": {"ar": "لا أسلاك ظاهرة", "en": "No visible cables", "ur": "کوئی تار نظر نہ آئے", "bn": "কোনো তার দেখা যাবে না", "hi": "कोई तार दिखे नहीं", "tl": "Walang nakikitang kable"}}]}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-F02$w$,$w$الجولة الميدانية الأسبوعية لبيئة الرعاية$w$,$w$مدير المنشأة ومشرف المرافق$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "جولة منظمة يرى فيها مدير المنشأة ما يراه المريض والمقيِّم: النظافة، السلامة، الأعطال الظاهرة، مسارات الإخلاء، وحالة الغرف. كل ملاحظة تُسجَّل على رقم الغرفة أو الأصل وتصبح بلاغاً (F-02، R-16)."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- ارتداء بطاقة التعريف، والالتزام بقيود مناطق العزل والعمليات"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- جوال بالمنصة للتصوير والتسجيل\n- قائمة مناطق الجولة لهذا الأسبوع"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | اختيار مسار الجولة (تُغطى كل المناطق خلال الشهر) | المسار محدد |\n| 2 | المداخل والانتظار: النظافة، المقاعد، الشاشات، الإرشاد | مسجل |\n| 3 | الممرات ومسارات الإخلاء: خالية، أبواب الحريق تغلق، لوحات المخارج مضاءة | مسجل |\n| 4 | دورات المياه: نظافة، تسريب، مستلزمات، إضاءة | مسجل |\n| 5 | الأسقف والجدران والأرضيات: تبقع، تكسر، رطوبة | مسجل |\n| 6 | الغرف الفنية: مغلقة، غير مستخدمة للتخزين | مسجل |\n| 7 | تسجيل كل ملاحظة بصورة ورقم الغرفة في المنصة كبلاغ | كل ملاحظة بلاغ |\n| 8 | مراجعة إغلاق ملاحظات الجولة السابقة | المتأخر مُصعّد |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| الجولة | أسبوعياً |\n| تغطية كل المناطق | شهرياً |\n| جولة مشتركة مع السلامة ومكافحة العدوى | ربع سنوي |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل ملاحظة لها بلاغ برقم غرفة\n- ملاحظات الجولة السابقة مغلقة أو مصعّدة"}, {"key": "donts", "title": "ممنوعات", "body": "- تسجيل ملاحظة بلا موقع\n- إصلاح مؤقت دون بلاغ\n- تجاوز مناطق دون تنسيق"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "F-02 · F-03 · G-01 · R-16"}]$w$::jsonb,'wi',108,$w$clipok$w$,$w$جولات المرافق$w$,$w$FAC$w$,$w$["اختيار مسار الجولة (تُغطى كل المناطق خلال الشهر)", "المداخل والانتظار: النظافة، المقاعد، الشاشات، الإرشاد", "الممرات ومسارات الإخلاء: خالية، أبواب الحريق تغلق، لوحات المخارج مضاءة", "دورات المياه: نظافة، تسريب، مستلزمات، إضاءة", "الأسقف والجدران والأرضيات: تبقع، تكسر، رطوبة", "الغرف الفنية: مغلقة، غير مستخدمة للتخزين", "تسجيل كل ملاحظة بصورة ورقم الغرفة في المنصة كبلاغ", "مراجعة إغلاق ملاحظات الجولة السابقة"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-F03$w$,$w$إغلاق غرفة أو منطقة للصيانة وإعادة فتحها$w$,$w$مدير المنشأة ومشرف الصيانة$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "لا تُغلق غرفة دون إشعار المستخدمين، ولا تُفتح بعد الأعمال دون فحص ومحضر (R-11). يحمي هذا العمل استمرار الخدمة وسلامة المرضى ومكافحة العدوى."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- تقييم مخاطر مكافحة العدوى (ICRA) للأعمال داخل المناطق السريرية\n- حواجز وغلق مناسب للمنطقة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- نموذج الإغلاق في المنصة\n- لوحات «مغلق للصيانة»\n- قائمة فحص إعادة الفتح"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | تسجيل طلب الإغلاق في المنصة: الغرفة، السبب، المدة، البديل | الطلب مسجل |\n| 2 | إشعار القسم المستخدم والجهات المعنية قبل الإغلاق | الإشعار تم |\n| 3 | تأمين المنطقة وتعليق اللوحات وتطبيق حواجز مكافحة العدوى | المنطقة مؤمنة |\n| 4 | متابعة الأعمال حتى انتهائها | الأعمال منتهية |\n| 5 | فحص قبل الفتح: النظافة النهائية، الأنظمة تعمل، لا مخلفات | الفحص ناجح |\n| 6 | توقيع محضر إعادة الفتح وإشعار القسم | المحضر موقع |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| عند كل إغلاق | قبل البدء وبعد الانتهاء |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا إغلاق بلا إشعار\n- لا فتح بلا محضر وفحص"}, {"key": "donts", "title": "ممنوعات", "body": "- إغلاق غرفة دون بديل للخدمة\n- فتح الغرفة قبل التنظيف النهائي"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "F-01 · G-12 · R-11"}]$w$::jsonb,'wi',109,$w$lock$w$,$w$جولات المرافق$w$,$w$FAC$w$,$w$["تسجيل طلب الإغلاق في المنصة: الغرفة، السبب، المدة، البديل", "إشعار القسم المستخدم والجهات المعنية قبل الإغلاق", "تأمين المنطقة وتعليق اللوحات وتطبيق حواجز مكافحة العدوى", "متابعة الأعمال حتى انتهائها", "فحص قبل الفتح: النظافة النهائية، الأنظمة تعمل، لا مخلفات", "توقيع محضر إعادة الفتح وإشعار القسم"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-I01$w$,$w$تجهيز نقطة شبكة وتوصيل جهاز جديد$w$,$w$فنيو تقنية المعلومات$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "يضمن أن كل جهاز جديد يُوصل بنقطة موثّقة ومعتمدة، ويُسجَّل في الأصول التقنية، ويُمنح صلاحياته وفق الحاجة (T-05، R-35). الأجهزة الطبية لا تُربط إلا بموافقة (R-34)."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- فصل الكهرباء عند العمل داخل الكبائن عند الحاجة\n- عدم فك أي كابل غير موسوم"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- جهاز اختبار الكابلات\n- ملصقات توسيم\n- سجل الأصول التقنية"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | التحقق من الطلب المعتمد وتحديد نوع الجهاز (إداري / طبي / شاشة / كاميرا) | الطلب معتمد |\n| 2 | للأجهزة الطبية: التأكد من موافقة الربط (T-03) | الموافقة موجودة |\n| 3 | تحديد النقطة ورقمها في الكبينة ومطابقة الوسم من الطرفين | الوسم مطابق |\n| 4 | اختبار النقطة بجهاز الاختبار | النقطة سليمة |\n| 5 | ضبط المنفذ في المفتاح على الشبكة الصحيحة (VLAN) | الشبكة صحيحة |\n| 6 | توصيل الجهاز واختبار الاتصال والخدمة | يعمل |\n| 7 | تسجيل الجهاز في الأصول التقنية بموقعه ونقطته | مسجل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| عند كل جهاز جديد | قبل التسليم للمستخدم |"}, {"key": "accept", "title": "معايير القبول", "body": "- النقطة موسومة ومختبرة\n- الجهاز مسجل بموقعه\n- لا جهاز طبي بلا موافقة"}, {"key": "donts", "title": "ممنوعات", "body": "- توصيل جهاز شخصي أو غير مسجل\n- استخدام نقطة غير موسومة\n- ربط جهاز طبي دون موافقة"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "T-02 · T-03 · T-05 · R-34 · R-35"}]$w$::jsonb,'wi',110,$w$link$w$,$w$البنية التقنية$w$,$w$IT$w$,$w$["التحقق من الطلب المعتمد وتحديد نوع الجهاز (إداري / طبي / شاشة / كاميرا)", "للأجهزة الطبية: التأكد من موافقة الربط (T-03)", "تحديد النقطة ورقمها في الكبينة ومطابقة الوسم من الطرفين", "اختبار النقطة بجهاز الاختبار", "ضبط المنفذ في المفتاح على الشبكة الصحيحة (VLAN)", "توصيل الجهاز واختبار الاتصال والخدمة", "تسجيل الجهاز في الأصول التقنية بموقعه ونقطته"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-I02$w$,$w$النسخ الاحتياطي واختبار الاستعادة$w$,$w$فنيو تقنية المعلومات$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "النسخة الاحتياطية لا قيمة لها حتى تُستعاد فعلاً (R-36). يحدد هذا العمل التحقق اليومي من النسخ، واختبار الاستعادة الدوري، وقاعدة 3-2-1: ثلاث نسخ، على وسيطين، وواحدة خارج الموقع."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- الاستعادة التجريبية في بيئة منفصلة لا على النظام العامل"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- نظام النسخ الاحتياطي\n- بيئة اختبار\n- سجل النسخ والاستعادة"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | مراجعة تقرير النسخ اليومي لكل الأنظمة الحرجة | كل المهام ناجحة |\n| 2 | معالجة أي فشل في اليوم نفسه وإعادة النسخ | لا فشل معلّق |\n| 3 | التحقق من وجود نسخة خارج الموقع أو معزولة | النسخة موجودة |\n| 4 | اختيار نظام واستعادته في بيئة الاختبار | الاستعادة تمت |\n| 5 | التحقق من سلامة البيانات المستعادة مع مالك النظام | البيانات سليمة |\n| 6 | تسجيل زمن الاستعادة ومقارنته بالمستهدف | ضمن المستهدف |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| مراجعة النسخ | يومياً |\n| اختبار الاستعادة | ربع سنوي لكل نظام حرج |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا يوم بلا نسخة ناجحة\n- استعادة مختبرة لكل نظام حرج خلال الربع"}, {"key": "donts", "title": "ممنوعات", "body": "- الاكتفاء بنجاح مهمة النسخ دون استعادة\n- حفظ كل النسخ في مكان واحد"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "T-04 · R-36"}]$w$::jsonb,'wi',111,$w$box$w$,$w$استمرارية الأنظمة$w$,$w$IT$w$,$w$["مراجعة تقرير النسخ اليومي لكل الأنظمة الحرجة", "معالجة أي فشل في اليوم نفسه وإعادة النسخ", "التحقق من وجود نسخة خارج الموقع أو معزولة", "اختيار نظام واستعادته في بيئة الاختبار", "التحقق من سلامة البيانات المستعادة مع مالك النظام", "تسجيل زمن الاستعادة ومقارنته بالمستهدف"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-I03$w$,$w$الفحص الأسبوعي لكاميرات المراقبة والتسجيل$w$,$w$فنيو تقنية المعلومات والأمن$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "الكاميرا تُقيَّم بما تسجله عند الحاجة: صورة واضحة ليلاً ونهاراً، وتسجيل محفوظ للمدة المطلوبة. يكشف هذا الفحص الكاميرات المتوقفة والمزاحة والأقراص الممتلئة قبل أن يُطلب تسجيل غير موجود."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- الاطلاع على التسجيلات للمخوّلين فقط"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- شاشة المراقبة ونظام التسجيل (NVR)\n- قائمة الكاميرات بمواقعها"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | مراجعة حالة كل كاميرا في النظام (متصلة / غير متصلة) | كل الكاميرات متصلة |\n| 2 | مقارنة زاوية كل كاميرا بصورتها المرجعية | الزوايا صحيحة |\n| 3 | فحص وضوح الصورة الليلية لعينة من الكاميرات | الصورة واضحة |\n| 4 | التحقق من مدة الحفظ الفعلية في الأقراص | تكفي المدة المطلوبة |\n| 5 | فحص حالة الأقراص وأخطاء النظام | لا أخطاء |\n| 6 | فتح أمر إصلاح لأي كاميرا معطلة أو مزاحة | الأوامر مفتوحة |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| حالة الكاميرات والتسجيل | أسبوعياً |\n| تنظيف العدسات الخارجية | كل 3 أشهر |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل الكاميرات تعمل وتسجل\n- مدة الحفظ متحققة"}, {"key": "donts", "title": "ممنوعات", "body": "- ترك كاميرا معطلة دون أمر إصلاح\n- إطلاع غير المخوّلين على التسجيلات"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "T-01 · H-05"}]$w$::jsonb,'wi',112,$w$camera$w$,$w$الأنظمة الأمنية$w$,$w$IT$w$,$w$["مراجعة حالة كل كاميرا في النظام (متصلة / غير متصلة)", "مقارنة زاوية كل كاميرا بصورتها المرجعية", "فحص وضوح الصورة الليلية لعينة من الكاميرات", "التحقق من مدة الحفظ الفعلية في الأقراص", "فحص حالة الأقراص وأخطاء النظام", "فتح أمر إصلاح لأي كاميرا معطلة أو مزاحة"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-B01$w$,$w$اختبار السلامة الكهربائية للأجهزة الطبية$w$,$w$مهندسو وفنيو الصيانة الطبية$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "يثبت أن الجهاز الطبي لا يعرّض المريض أو المستخدم لتيار تسرب خطر. يُنفّذ عند الاستلام وبعد كل إصلاح ودورياً حسب خطورة الجهاز. المرجع IEC 62353 وتوصيات الصانع."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- الاختبار والجهاز غير موصول بمريض\n- إبعاد السوائل عن منطقة الاختبار"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- جهاز اختبار السلامة الكهربائية المعاير\n- سجل الجهاز في المنصة"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | التحقق من هوية الجهاز ورقمه في سجل الأجهزة الطبية | الجهاز مسجل |\n| 2 | الفحص البصري: الكابل، القابس، الهيكل، الملصقات | سليم |\n| 3 | قياس مقاومة الأرضي الواقي (للأجهزة Class I) | لا تتجاوز 0.3 أوم |\n| 4 | قياس تيار التسرب للجهاز والأجزاء التطبيقية | ضمن حدود IEC 62353 |\n| 5 | اختبار تشغيلي للوظائف الأساسية | يعمل |\n| 6 | لصق ملصق الاختبار بالتاريخ والموعد القادم | الملصق موجود |\n| 7 | تسجيل النتائج في المنصة | مسجل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| عند الاستلام وبعد الإصلاح | إلزامي |\n| الدوري | سنوياً للأجهزة عالية الخطورة، وحسب الصانع لغيرها |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل القياسات ضمن الحدود\n- ملصق اختبار ساري على الجهاز"}, {"key": "donts", "title": "ممنوعات", "body": "- إعادة جهاز للخدمة بعد إصلاح دون اختبار\n- استخدام وصلات تمديد غير طبية مع الأجهزة الطبية"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "B-02 · G-08"}]$w$::jsonb,'wi',113,$w$pulse$w$,$w$السلامة والمعايرة$w$,$w$BME$w$,$w$["التحقق من هوية الجهاز ورقمه في سجل الأجهزة الطبية", "الفحص البصري: الكابل، القابس، الهيكل، الملصقات", "قياس مقاومة الأرضي الواقي (للأجهزة Class I)", "قياس تيار التسرب للجهاز والأجزاء التطبيقية", "اختبار تشغيلي للوظائف الأساسية", "لصق ملصق الاختبار بالتاريخ والموعد القادم", "تسجيل النتائج في المنصة"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-B02$w$,$w$الفحص الدوري لجهاز الصدمات (AED) وعربة الإنعاش$w$,$w$التمريض المسؤول والصيانة الطبية$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "جهاز الصدمات وعربة الإنعاش يجب أن يكونا جاهزين في أي لحظة. يحدد هذا العمل الفحص اليومي من القسم والفحص الدوري من الصيانة الطبية."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- عدم اختبار الصدمة إلا بأداة الاختبار المعتمدة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- قائمة فحص العربة\n- أداة اختبار جهاز الصدمات"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | التحقق من مؤشر الجاهزية في الجهاز | المؤشر سليم |\n| 2 | فحص تاريخ صلاحية الأقطاب (Pads) والبطارية | سارية |\n| 3 | فحص محتويات عربة الإنعاش وأختامها حسب القائمة | كاملة |\n| 4 | اختبار الجهاز الدوري بأداة الاختبار (الصيانة الطبية) | ناجح |\n| 5 | تسجيل الفحص في سجل العربة والمنصة | مسجل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| مؤشر الجاهزية وختم العربة | يومياً من القسم |\n| الاختبار الوظيفي | كل 6 أشهر من الصيانة الطبية |"}, {"key": "accept", "title": "معايير القبول", "body": "- الجهاز جاهز والأقطاب سارية\n- العربة مكتملة ومختومة"}, {"key": "donts", "title": "ممنوعات", "body": "- ترك أقطاب منتهية\n- فتح ختم العربة دون إعادة الجرد"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "B-02"}]$w$::jsonb,'wi',114,$w$bolt$w$,$w$أجهزة الطوارئ$w$,$w$BME$w$,$w$["التحقق من مؤشر الجاهزية في الجهاز", "فحص تاريخ صلاحية الأقطاب (Pads) والبطارية", "فحص محتويات عربة الإنعاش وأختامها حسب القائمة", "اختبار الجهاز الدوري بأداة الاختبار (الصيانة الطبية)", "تسجيل الفحص في سجل العربة والمنصة"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-B03$w$,$w$مراقبة حرارة ثلاجات اللقاحات والأدوية$w$,$w$التمريض المسؤول والصيانة الطبية$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "اللقاحات تفقد فعاليتها خارج المدى +2 إلى +8°م. يضمن هذا العمل تسجيل الحرارة والتصرف الفوري عند الانحراف وصيانة الثلاجة ومسجل الحرارة."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- عدم فتح الثلاجة أكثر من الحاجة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- ثلاجة طبية بمسجل حرارة ومنبه\n- سجل الحرارة"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | قراءة الحرارة الحالية والعظمى والصغرى وتسجيلها | بين +2 و+8°م |\n| 2 | عند الانحراف: نقل المحتويات لثلاجة بديلة فوراً وعزلها | تم النقل |\n| 3 | إبلاغ الصيانة الطبية والصيدلية بالانحراف ومدته | تم الإبلاغ |\n| 4 | فحص الباب والجوان وعدم ازدحام الثلاجة | سليم |\n| 5 | التحقق من عمل المنبه ومعايرة المسجل دورياً | يعمل |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| قراءة الحرارة | مرتين يومياً |\n| معايرة المسجل والصيانة الوقائية | سنوياً |"}, {"key": "accept", "title": "معايير القبول", "body": "- الحرارة ضمن المدى في كل القراءات\n- كل انحراف موثق ومعالج"}, {"key": "donts", "title": "ممنوعات", "body": "- حفظ الطعام في ثلاجة اللقاحات\n- إطفاء المنبه دون معالجة السبب"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "B-02"}]$w$::jsonb,'wi',115,$w$steth$w$,$w$سلسلة التبريد$w$,$w$BME$w$,$w$["قراءة الحرارة الحالية والعظمى والصغرى وتسجيلها", "عند الانحراف: نقل المحتويات لثلاجة بديلة فوراً وعزلها", "إبلاغ الصيانة الطبية والصيدلية بالانحراف ومدته", "فحص الباب والجوان وعدم ازدحام الثلاجة", "التحقق من عمل المنبه ومعايرة المسجل دورياً"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-T01$w$,$w$فحص السيارة عند التسليم والاستلام$w$,$w$مسؤول الحركة والسائقون$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "يوثّق حالة السيارة عند تسليمها للمهمة وعند عودتها في اليوم نفسه، فتُعرف المسؤولية عن أي ضرر أو مخالفة (V-01، R-37، R-39)."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- فحص السيارة وهي متوقفة والمحرك مطفأ"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- نموذج التسليم في المنصة\n- جوال للتصوير"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | مطابقة السيارة والمستلم والمهمة في المنصة | مطابق |\n| 2 | تصوير السيارة من الجهات الأربع والعداد ومستوى الوقود | الصور مرفوعة |\n| 3 | فحص الإطارات والأنوار والزجاج والإطار الاحتياطي والطفاية | سليمة |\n| 4 | التحقق من سريان الاستمارة والتأمين | سارية |\n| 5 | عند العودة: تكرار الصور والعداد والوقود | مسجل |\n| 6 | تسجيل أي ضرر جديد أو مخالفة على مستخدم السيارة وقتها | موثق |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| عند كل تسليم واستلام | إلزامي |"}, {"key": "accept", "title": "معايير القبول", "body": "- صور قبل وبعد لكل مهمة\n- العودة في اليوم نفسه"}, {"key": "donts", "title": "ممنوعات", "body": "- تسليم سيارة دون محضر\n- تسليم سيارة بوثيقة منتهية"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "V-01 · V-02 · R-37 · R-39 · R-41"}]$w$::jsonb,'wi',116,$w$car$w$,$w$سيارات المقر$w$,$w$TRN$w$,$w$["مطابقة السيارة والمستلم والمهمة في المنصة", "تصوير السيارة من الجهات الأربع والعداد ومستوى الوقود", "فحص الإطارات والأنوار والزجاج والإطار الاحتياطي والطفاية", "التحقق من سريان الاستمارة والتأمين", "عند العودة: تكرار الصور والعداد والوقود", "تسجيل أي ضرر جديد أو مخالفة على مستخدم السيارة وقتها"]$w$::jsonb,$w${"steps": [{"i": "camera", "t": {"ar": "صوّر السيارة من الجهات الأربع", "en": "Photograph all four sides", "ur": "گاڑی کی چاروں طرف سے تصویر لیں", "bn": "গাড়ির চার দিকের ছবি তুলুন", "hi": "गाड़ी की चारों तरफ से फोटो लें", "tl": "Kunan ang apat na gilid ng sasakyan"}}, {"i": "gauge", "t": {"ar": "صوّر العداد والوقود", "en": "Photograph odometer and fuel", "ur": "میٹر اور ایندھن کی تصویر لیں", "bn": "মিটার ও জ্বালানির ছবি তুলুন", "hi": "मीटर और ईंधन की फोटो लें", "tl": "Kunan ang odometer at gasolina"}}, {"i": "check", "t": {"ar": "افحص الإطارات والأنوار والطفاية", "en": "Check tyres, lights, extinguisher", "ur": "ٹائر، لائٹ، آگ بجھانے والا آلہ چیک کریں", "bn": "টায়ার, লাইট, অগ্নিনির্বাপক দেখুন", "hi": "टायर, लाइट, अग्निशामक जांचें", "tl": "Suriin ang gulong, ilaw, extinguisher"}}, {"i": "clock", "t": {"ar": "أعد السيارة في اليوم نفسه", "en": "Return the car the same day", "ur": "گاڑی اسی دن واپس کریں", "bn": "একই দিনে গাড়ি ফেরত দিন", "hi": "गाड़ी उसी दिन लौटाएं", "tl": "Ibalik ang sasakyan sa parehong araw"}}], "donts": [{"i": "noentry", "t": {"ar": "لا تسلّم دون محضر", "en": "No handover without a record", "ur": "ریکارڈ کے بغیر حوالگی نہیں", "bn": "রেকর্ড ছাড়া হস্তান্তর নয়", "hi": "रिकॉर्ड के बिना सौंपना नहीं", "tl": "Walang pag-abot nang walang tala"}}]}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-P01$w$,$w$فحص الأعمال قبل الإخفاء$w$,$w$مهندسو المشاريع والمقاولون$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "لا يُغطّى أي عمل (تمديدات داخل الجدران والأسقف، عزل قبل التبليط، حديد قبل الصب) قبل فحصه وتوثيقه. يحمي هذا العمل المنشأة من عيوب مخفية يصعب كشفها بعد التسليم (HO-04)."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- الالتزام بتصريح العمل وأدوات السلامة في الموقع (H-07)"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- طلب الفحص من المقاول\n- المخططات المعتمدة ومخططات الورشة\n- جوال المنصة للتصوير"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | استلام طلب الفحص من المقاول قبل 24 ساعة على الأقل بالموقع والتخصص | الطلب مسجل |\n| 2 | المطابقة مع المخططات ومخططات الورشة المعتمدة | مطابق |\n| 3 | التحقق من المواد المركبة مقابل الاعتماد (الموديل والمصنّع) | المواد معتمدة |\n| 4 | حضور الاختبارات المطلوبة (ضغط المواسير، العزل، الغمر) | الاختبار ناجح |\n| 5 | التصوير المؤرخ لكل منطقة قبل الإخفاء | الصور مرفوعة |\n| 6 | الموافقة أو الرفض كتابياً مع الملاحظات في محضر | المحضر موقع |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| قبل كل إخفاء | إلزامي |"}, {"key": "accept", "title": "معايير القبول", "body": "- لا إخفاء بلا محضر فحص\n- صور مؤرخة لكل منطقة"}, {"key": "donts", "title": "ممنوعات", "body": "- السماح بالإغلاق قبل الفحص\n- قبول مواد غير معتمدة"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "P-05 · P-06 · P-12 · HO-04"}]$w$::jsonb,'wi',117,$w$check$w$,$w$الإشراف على التنفيذ$w$,$w$PRJ$w$,$w$["استلام طلب الفحص من المقاول قبل 24 ساعة على الأقل بالموقع والتخصص", "المطابقة مع المخططات ومخططات الورشة المعتمدة", "التحقق من المواد المركبة مقابل الاعتماد (الموديل والمصنّع)", "حضور الاختبارات المطلوبة (ضغط المواسير، العزل، الغمر)", "التصوير المؤرخ لكل منطقة قبل الإخفاء", "الموافقة أو الرفض كتابياً مع الملاحظات في محضر"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon,cat,unit,checklist,card) values ($w$WI-P02$w$,$w$استلام المواد في الموقع ومطابقتها للاعتماد$w$,$w$مهندسو المشاريع والمقاولون$w$,$w$[{"key": "purpose", "title": "الغرض والنطاق", "body": "كل مادة تصل الموقع تُطابق مع طلب الاعتماد المعتمد ومع سجل المواد والمصنّعين المعتمدين ودليل المواصفات: الموديل، المصنّع، رقم الدفعة، الملصقات. المادة غير المطابقة تُرفض ولا تُركّب."}, {"key": "safety", "title": "السلامة ومعدات الوقاية", "body": "- فحص المواد في مكان آمن بعيداً عن الحركة"}, {"key": "tools", "title": "الأدوات والمواد", "body": "- طلب الاعتماد المعتمد\n- سجل المواد والمصنّعين المعتمدين في المنصة\n- دليل المواصفات المعتمدة للمشروع"}, {"key": "steps", "title": "خطوات التنفيذ", "body": "| # | الخطوة | التحقق |\n| 1 | مطابقة المادة مع طلب الاعتماد المعتمد (P-06) | مطابقة |\n| 2 | مطابقة المصنّع مع سجل المواد المعتمدة وشرطه (حصراً / القائمة / ما يعادله) | المصنّع معتمد |\n| 3 | فحص الملصقات وأرقام الدفعة وشهادات المنشأ والمطابقة | سليمة |\n| 4 | فحص الحالة الظاهرة: لا تلف ولا رطوبة ولا انتهاء صلاحية | سليمة |\n| 5 | تسجيل الاستلام بصور الملصقات في المنصة | مسجل |\n| 6 | رفض غير المطابق كتابياً وإخراجه من الموقع | موثق |"}, {"key": "freq", "title": "التكرار", "body": "| العمل | التكرار |\n| عند كل توريد | إلزامي |"}, {"key": "accept", "title": "معايير القبول", "body": "- كل مادة مطابقة لاعتمادها وللسجل\n- أرقام الدفعات موثقة لسجل المواد المنفذة (HO-03)"}, {"key": "donts", "title": "ممنوعات", "body": "- قبول مادة بديلة دون اعتماد كتابي\n- تخزين مادة مرفوضة في الموقع"}, {"key": "checklist", "title": "قائمة التحقق في المنصة", "body": "هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.", "auto": "checklist"}, {"key": "refs", "title": "المراجع والإجراءات", "body": "الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.", "auto": "procs", "procs": "P-06 · P-05 · HO-03"}]$w$::jsonb,'wi',118,$w$box$w$,$w$الإشراف على التنفيذ$w$,$w$PRJ$w$,$w$["مطابقة المادة مع طلب الاعتماد المعتمد (P-06)", "مطابقة المصنّع مع سجل المواد المعتمدة وشرطه (حصراً / القائمة / ما يعادله)", "فحص الملصقات وأرقام الدفعة وشهادات المنشأ والمطابقة", "فحص الحالة الظاهرة: لا تلف ولا رطوبة ولا انتهاء صلاحية", "تسجيل الاستلام بصور الملصقات في المنصة", "رفض غير المطابق كتابياً وإخراجه من الموقع"]$w$::jsonb,$w${}$w$::jsonb) on conflict (code) do nothing;
